"""Kushmanda `results.json` → markdown. Generated, never typed."""

from __future__ import annotations

import json
import sys


def main(path: str) -> int:
    with open(path, encoding="utf-8") as handle:
        r = json.load(handle)
    c, t, h = r["corpus"], r["tokenizer"], r["held_out"]
    gpt2 = t.get("gpt2_tokens_per_line_held_out")
    out = [
        "<!-- Generated by packages/sati/sati/lm/report.py from the Kaggle training run. Do not edit by hand. -->\n",
        "# Kushmanda v0 — Sati's own language model\n",
        f"A {r['parameters'] / 1e6:.1f}M-parameter decoder, written from scratch and trained from random "
        f"initialisation on {c['documents']:,} documents of permissively licensed security text "
        f"({', '.join(f'{k}: {v:,}' for k, v in c['by_source'].items())}), {r['steps']:,} steps on `{r['device']}`. "
        f"{c['held_out_documents']:,} documents were held out, by document.\n",
        "## Held-out text\n",
        "| Measure | Value |",
        "|---|---:|",
        f"| Loss | {h['loss']} |",
        f"| Perplexity (own tokens) | {h['perplexity']} |",
        f"| Bits per byte | {h['bits_per_byte']} |",
        "",
        "Bits per byte is the comparable number: perplexity depends on the tokenizer, bits per byte does not.\n",
        "## Its own tokenizer (RP-41)\n",
        "| Tokenizer | Vocabulary | Tokens per held-out line |",
        "|---|---:|---:|",
        f"| **Kushmanda BPE** (trained on this corpus) | {t['vocab']:,} | {t['tokens_per_line_held_out']} |",
        f"| GPT-2 (generic) | 50,257 | {gpt2 if gpt2 is not None else '—'} |",
        "",
        "## Sample completions\n",
        "Unedited, from the held-out-trained model. A small narrow model: fluent in the domain's vocabulary, "
        "not a source of facts — which is why Sati never treats generated text as evidence (rule 1).\n",
    ]
    for s in r["samples"]:
        out.append(f"- **{s['prompt']}**{s['completion']}")
    out += [
        "",
        "Designed, written and trained by an AI assistant under the owner's direction "
        "([adr/RealDataModels](../../adr/RealDataModels.md)).",
    ]
    print("\n".join(out))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1]))
